commands.pipeline.ps1:
$ErrorActionPreference='Stop'
Set-Location O:/repos.hobby/ntvdm64
try {
 if((Get-Content "$PSScriptRoot/cached.exit").Trim() -ne '0'){throw 'Cached build failed'}
 $hostPath=(Get-Process -Id $PID).Path
 foreach($step in @('stage','publish-before-full','full-final','final-check')) {
  & $hostPath -NoProfile -File "$PSScriptRoot/$step.ps1" *> "$PSScriptRoot/$step.log"
  if($LASTEXITCODE){throw "$step failed"}
 }
 0|Set-Content "$PSScriptRoot/pipeline.exit"
} catch {$_|Out-String|Write-Output;1|Set-Content "$PSScriptRoot/pipeline.exit";exit 1}

commands.final-check.ps1:
$ErrorActionPreference='Stop'
Set-Location O:/repos.hobby/ntvdm64
try {
 & python build/t483-s5-p118/compare.py
 if($LASTEXITCODE){throw 'Entry object code changed unexpectedly'}
 & tools/audit/verify-wow-shared-boundary.ps1 -WowBuildRoot build/.ninja/msvc-x86-release/wow32
 if($LASTEXITCODE){throw 'Boundary failed'}
 & tools/governance/Verify-DocumentationGovernance.ps1
 if($LASTEXITCODE){throw 'Governance failed'}
 & tools/governance/Test-DocumentationRelativeLinks.ps1
 if($LASTEXITCODE){throw 'Links failed'}
 git diff --check
 if($LASTEXITCODE){throw 'Diff check failed'}
 0|Set-Content build/t483-s5-p118/final-check.exit
}catch{$_|Out-String|Write-Output;1|Set-Content build/t483-s5-p118/final-check.exit;exit 1}
